def calculate(expression):
    def helper(s, idx):
        stack = []
        num = 0
        sign = '+'
        while idx < len(s):
            c = s[idx]
            if c.isdigit():
                num = num * 10 + int(c)
            if c == '(':
                num, idx = helper(s, idx + 1)
            if c in '+-*/)' or idx == len(s) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    prev = stack.pop()
                    stack.append(int(prev / num))
                num = 0
                sign = c
