def skyline(buildings):
    import heapq
    if not buildings:
        return []
    events = []
    for l, r, h in buildings:
        events.append((l, -h, r))
        events.append((r, 0, 0))
    events.sort()
    result = [[0, 0]]
    heap = [(0, float('inf'))]
    for x, neg_h, r in events:
        if neg_h:
            heapq.heappush(heap, (neg_h, r))
        while heap[0][1] <= x:
            heapq.heappop(heap)
        max_h = -heap[0][0]
        if result[-1][1] != max_h:
            result.append([x, max_h])
    return result[1:]

